create extension if not exists pgcrypto;
create type public.order_status as enum ('pending','accepted','preparing','ready','out_for_delivery','delivered','cancelled');
create type public.payment_status as enum ('unpaid','pending','paid','failed','refunded');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role text not null default 'customer' check (role in ('customer','staff','admin','driver')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.menu_items (id uuid primary key default gen_random_uuid(), name text not null, description text, category text not null default 'indomie', price numeric(12,2) not null check (price >= 0), image_url text, is_available boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id), customer_name text not null, customer_phone text not null, delivery_address text not null, status public.order_status not null default 'pending', payment_status public.payment_status not null default 'unpaid', subtotal numeric(12,2) not null check (subtotal >= 0), delivery_fee numeric(12,2) not null default 0, total numeric(12,2) generated always as (subtotal + delivery_fee) stored, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, menu_item_id uuid references public.menu_items(id) on delete set null, item_name text not null, unit_price numeric(12,2) not null, quantity int not null check (quantity > 0), line_total numeric(12,2) generated always as (unit_price * quantity) stored);
create table public.order_events (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, status public.order_status not null, message text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create index orders_user_id_idx on public.orders(user_id); create index orders_status_idx on public.orders(status); create index order_items_order_id_idx on public.order_items(order_id);
alter table public.profiles enable row level security; alter table public.menu_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.order_events enable row level security;
create policy "public can read available menu" on public.menu_items for select using (is_available = true or auth.uid() is not null);
create policy "users read own orders" on public.orders for select using (user_id = auth.uid());
create policy "users create own orders" on public.orders for insert with check (user_id = auth.uid() or user_id is null);
create policy "users read own order items" on public.order_items for select using (exists(select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create policy "users read own order events" on public.order_events for select using (exists(select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email)); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
